"""Feedback-based continuation; no reset and no assumption that TCP is the tip."""

import inspect
import math
import statistics


_INITIAL_TCP = [0.4564, 0.0656, 0.1672]
_TOP_Z = 0.05
_CLEARANCE = 0.005
_STEP = 0.00025
_FORCE_LIMIT = 8.0
_TORQUE_LIMIT = 1.0


def _method(api, names):
    for name in names:
        fn = getattr(api, name, None)
        if callable(fn):
            return fn
    return None


def _position(value):
    if isinstance(value, dict):
        for key in ("tcp", "tcp_pose", "position", "pos", "pose", "actual_pose"):
            if key in value:
                result = _position(value[key])
                if result is not None:
                    return result
        if all(k in value for k in ("x", "y", "z")):
            return [float(value[k]) for k in ("x", "y", "z")]
    elif isinstance(value, (list, tuple)):
        if len(value) >= 3 and all(
            isinstance(v, (int, float)) for v in value[:3]
        ):
            return [float(v) for v in value[:3]]
        if value:
            return _position(value[0])
    return None


def _yaw(value):
    if isinstance(value, dict):
        for key in ("yaw", "tcp_yaw", "actual_yaw"):
            if key in value:
                return float(value[key])
        for key in ("tcp_pose", "pose"):
            if key in value:
                return _yaw(value[key])
    elif isinstance(value, (list, tuple)):
        if len(value) == 2 and isinstance(value[1], (int, float)):
            return float(value[1])
        if len(value) == 4 and all(
            isinstance(v, (int, float)) for v in value
        ):
            return float(value[3])
    return None


def _loads(value):
    """Return force and torque magnitudes, or None for an unknown format."""
    if isinstance(value, dict):
        if "wrench" in value:
            return _loads(value["wrench"])
        force = value.get("force", value.get("forces"))
        torque = value.get("torque", value.get("torques"))
        if force is None and all(k in value for k in ("fx", "fy", "fz")):
            force = [value[k] for k in ("fx", "fy", "fz")]
        if force is not None:
            if isinstance(force, (int, float)):
                f = abs(float(force))
            else:
                f = math.sqrt(sum(float(v) ** 2 for v in force[:3]))
            t = 0.0
            if torque is not None:
                t = math.sqrt(sum(float(v) ** 2 for v in torque[:3]))
            return f, t
    elif isinstance(value, (int, float)):
        return abs(float(value)), 0.0
    elif isinstance(value, (list, tuple)):
        if len(value) == 2 and isinstance(value[0], (list, tuple)):
            return _loads({"force": value[0], "torque": value[1]})
        if len(value) >= 3:
            f = math.sqrt(sum(float(v) ** 2 for v in value[:3]))
            t = math.sqrt(sum(float(v) ** 2 for v in value[3:6]))
            return f, t
    return None


class _Cell:
    """Bind explicit Cartesian position/yaw APIs without guessing pose encodings."""

    def __init__(self, api):
        self.api = api
        self.read_pose = _method(
            api,
            ("tcp_pose", "get_tcp_pose", "get_tcp", "get_pose",
             "pose", "get_state", "state"),
        )
        self.read_force = _method(
            api,
            ("get_wrench", "wrench", "get_tcp_wrench", "tcp_wrench",
             "get_force", "force", "forces"),
        )
        self.p = list(_INITIAL_TCP)
        self.angle = None
        self.last_result = None
        if self.read_pose is not None:
            value = self.read_pose()
            p = _position(value)
            if p is None:
                raise RuntimeError("Cannot decode actual TCP position.")
            self.p = p
            self.angle = _yaw(value)

        self.move_fn = None
        for name in (
            "move_tcp", "move_to", "move_cartesian", "move",
            "set_tcp_pose", "move_relative", "move_rel",
        ):
            fn = getattr(api, name, None)
            if not callable(fn):
                continue
            try:
                parameters = inspect.signature(fn).parameters
            except (TypeError, ValueError):
                continue
            names = set(parameters)
            has_position = (
                {"x", "y", "z"} <= names
                or {"dx", "dy", "dz"} <= names
                or bool(names & {
                    "position", "pos", "xyz", "target_position", "target_pos"
                })
            )
            has_yaw = bool(names & {"yaw", "target_yaw", "theta", "dyaw"})
            if has_position and has_yaw:
                self.move_fn = fn
                self.parameters = parameters
                break

        if self.move_fn is None:
            raise RuntimeError(
                "A Cartesian move API with explicit position and yaw is required."
            )

        self.baseline = self.load() or (0.0, 0.0)

    def done(self):
        return bool(self.api.done())

    def load(self):
        if self.read_force is not None:
            return _loads(self.read_force())
        if isinstance(self.last_result, dict):
            return _loads(self.last_result)
        return None

    def overloaded(self):
        load = self.load()
        return load is not None and (
            load[0] > self.baseline[0] + _FORCE_LIMIT
            or load[1] > self.baseline[1] + _TORQUE_LIMIT
        )

    def move(self, p, yaw, speed=0.005):
        if self.done():
            return False

        p = [float(v) for v in p]
        if not all(math.isfinite(v) for v in p + [yaw]):
            raise RuntimeError("Non-finite motion target.")
        if not (0.25 <= p[0] <= 0.60 and -0.20 <= p[1] <= 0.20):
            raise RuntimeError("Motion outside the insertion-cell workspace.")
        if not (_TOP_Z - 0.034 <= p[2] <= 0.25):
            raise RuntimeError("Unsafe vertical target.")

        values = {
            "x": p[0], "y": p[1], "z": p[2],
            "dx": p[0] - self.p[0],
            "dy": p[1] - self.p[1],
            "dz": p[2] - self.p[2],
            "position": p, "pos": p, "xyz": p,
            "target_position": p, "target_pos": p,
            "yaw": yaw, "target_yaw": yaw, "theta": yaw,
            "speed": speed, "velocity": speed,
            "acceleration": 0.05,
            "force_limit": _FORCE_LIMIT,
            "max_force": _FORCE_LIMIT,
            "blocking": True, "wait": True,
        }
        if "dyaw" in self.parameters:
            if self.angle is None:
                raise RuntimeError("Relative yaw motion requires measured yaw.")
            values["dyaw"] = math.atan2(
                math.sin(yaw - self.angle), math.cos(yaw - self.angle)
            )

        args, kwargs = [], {}
        for name, param in self.parameters.items():
            if param.kind in (
                inspect.Parameter.VAR_POSITIONAL,
                inspect.Parameter.VAR_KEYWORD,
            ):
                continue
            if name in values:
                value = values[name]
            elif param.default is not inspect.Parameter.empty:
                value = param.default
            else:
                raise RuntimeError("Unsupported required motion argument: " + name)
            if param.kind == inspect.Parameter.POSITIONAL_ONLY:
                args.append(value)
            else:
                kwargs[name] = value

        self.last_result = self.move_fn(*args, **kwargs)
        if self.done():
            return False

        state = (
            self.read_pose() if self.read_pose is not None
            else self.last_result
        )
        actual = _position(state)
        if actual is None:
            raise RuntimeError(
                "Insertion requires actual TCP feedback, not commanded position."
            )
        self.p = actual
        measured_yaw = _yaw(state)
        self.angle = yaw if measured_yaw is None else measured_yaw
        return True

    def retract(self, z, yaw):
        if not self.move([self.p[0], self.p[1], z], yaw):
            return False
        if self.p[2] < z - 0.0005:
            raise RuntimeError("Retraction failed; do not translate or rotate.")
        if self.overloaded():
            raise RuntimeError("Persistent load after retraction.")
        return True


def run(api):
    if api.done():
        return

    cell = _Cell(api)

    # The earlier readings disagree with the nominal placement range.
    # Treat that range as a prior, not a reason to clamp measured coordinates.
    observations = []
    for _ in range(64):
        position, yaw = api.hole_pose()
        if (
            len(position) >= 3
            and all(math.isfinite(float(v)) for v in position[:3])
            and math.isfinite(float(yaw))
        ):
            observations.append((list(position), float(yaw)))
    if len(observations) < 16:
        raise RuntimeError("Insufficient valid hole observations.")

    cx = statistics.median(p[0] for p, _ in observations)
    cy = statistics.median(p[1] for p, _ in observations)
    yaw0 = math.atan2(
        sum(math.sin(a) for _, a in observations),
        sum(math.cos(a) for _, a in observations),
    )
    # Square symmetry permits the nearest equivalent orientation.
    yaw0 = (yaw0 + math.pi / 4) % (math.pi / 2) - math.pi / 4

    if not (0.30 <= cx <= 0.55 and -0.15 <= cy <= 0.15):
        raise RuntimeError("Hole estimate is outside the plausible workspace.")

    safe_z = max(cell.p[2], 0.145)
    initial_yaw = cell.angle if cell.angle is not None else yaw0
    if not cell.retract(safe_z, initial_yaw):
        return

    # Touch a solid patch overlapping the hole's rim. This measures the TCP
    # height at tip contact, avoiding an unsupported TCP-to-tip assumption.
    touch_x = cx + 0.018 * math.cos(yaw0)
    touch_y = cy + 0.018 * math.sin(yaw0)
    if not cell.move([touch_x, touch_y, safe_z], yaw0, speed=0.015):
        return

    surface_tcp_z = None
    while cell.p[2] > _TOP_Z - 0.001:
        before = cell.p[2]
        step = 0.001 if before > 0.135 else _STEP
        target = max(_TOP_Z - 0.001, before - step)
        if not cell.move([touch_x, touch_y, target], yaw0):
            return

        if cell.overloaded() or cell.p[2] > target + 0.00010:
            # Use the previous, unloaded height as a conservative reference.
            surface_tcp_z = before
            break

        if before - cell.p[2] < step * 0.25:
            surface_tcp_z = before
            break

    if surface_tcp_z is None:
        cell.retract(safe_z, yaw0)
        raise RuntimeError("No observable rim contact; refusing blind insertion.")

    approach_z = surface_tcp_z + _CLEARANCE
    if not cell.retract(approach_z, yaw0):
        return

    def probe(x, y, angle):
        if not cell.retract(approach_z, cell.angle):
            return True
        if not cell.move([x, y, approach_z], angle):
            return True
        if math.hypot(cell.p[0] - x, cell.p[1] - y) > 0.0003:
            raise RuntimeError("Lateral target was not reached.")

        if not cell.move([x, y, surface_tcp_z + 0.001], angle):
            return True
        if cell.overloaded():
