"""Continue the existing trial without resetting the simulator."""

import inspect
import math


class _Finished(Exception):
    pass


def _number(x):
    return isinstance(x, (int, float)) and math.isfinite(x)


def _pose(value):
    """Return (position, yaw), allowing yaw to be unavailable."""
    if isinstance(value, dict):
        for key in ("tcp_pose", "tcp", "pose", "observation", "state"):
            if key in value:
                result = _pose(value[key])
                if result is not None:
                    p, yaw = result
                    return p, value.get("yaw", yaw)

        p = value.get("position", value.get("pos"))
        if p is None and all(k in value for k in ("x", "y", "z")):
            p = [value["x"], value["y"], value["z"]]
        if isinstance(p, (list, tuple)) and len(p) >= 3:
            if all(_number(v) for v in p[:3]):
                yaw = value.get("yaw")
                if yaw is None:
                    rpy = value.get("rpy")
                    if isinstance(rpy, (list, tuple)) and len(rpy) == 3:
                        yaw = rpy[2]
                return list(p[:3]), yaw if _number(yaw) else None

    if isinstance(value, (list, tuple)):
        if len(value) == 2 and isinstance(value[0], (list, tuple)):
            p, yaw = value
            if len(p) >= 3 and all(_number(v) for v in p[:3]):
                return list(p[:3]), yaw if _number(yaw) else None
        if len(value) in (3, 4, 6) and all(_number(v) for v in value):
            yaw = value[-1] if len(value) in (4, 6) else None
            return list(value[:3]), yaw
    return None


def _force(value, direct=False):
    if isinstance(value, dict):
        for key in ("force", "contact_force", "wrench", "tcp_wrench"):
            if key in value:
                result = _force(value[key], True)
                if result is not None:
                    return result
        if all(k in value for k in ("fx", "fy", "fz")):
            return tuple(value[k] for k in ("fx", "fy", "fz"))
        for key in ("observation", "state"):
            if key in value:
                result = _force(value[key])
                if result is not None:
                    return result
    if direct:
        if _number(value):
            return (float(value),)
        if isinstance(value, (list, tuple)) and len(value) >= 3:
            if all(_number(v) for v in value[:3]):
                return tuple(value[:3])
    return None


def _zero_argument_methods(api, names):
    methods = []
    for name in names:
        fn = getattr(api, name, None)
        if not callable(fn):
            continue
        try:
            inspect.signature(fn).bind()
        except (TypeError, ValueError):
            continue
        methods.append(fn)
    return methods


class _Motion:
    """Bind documented Cartesian parameter names, not guessed joint actions."""

    POSITIONS = {"position", "pos", "xyz", "target_position", "target_pos"}
    DELTAS = {"delta", "delta_pos", "delta_position", "dpos", "displacement"}
    YAWS = {"yaw", "target_yaw", "theta"}
    DYAWS = {"dyaw", "delta_yaw", "yaw_delta", "d_yaw", "dtheta"}

    def __init__(self, fn, name, rotation_only=False):
        self.fn = fn
        self.signature = inspect.signature(fn)
        self.mapping = {}
        self.has_position = False
        self.has_yaw = False
        self.absolute_yaw = False
        self.force_limited = False

        relative = any(word in name for word in ("relative", "delta", "translate"))
        doc = (inspect.getdoc(fn) or "").lower()
        if "relative" in doc and "absolute" not in doc:
            relative = True

        for p in self.signature.parameters.values():
            k = p.name.lower()
            kind = None

            if k in self.POSITIONS:
                kind = "dp" if relative else "p"
                self.has_position = True
            elif k in self.DELTAS:
                kind = "dp"
                self.has_position = True
            elif k in ("x", "y", "z"):
                kind = ("d" if relative else "") + k
                self.has_position = True
            elif k in ("dx", "dy", "dz"):
                kind = k
                self.has_position = True
            elif k in self.YAWS:
                kind = "dyaw" if relative else "yaw"
                self.has_yaw = True
                self.absolute_yaw = not relative
            elif k in self.DYAWS:
                kind = "dyaw"
                self.has_yaw = True
            elif rotation_only and k == "angle":
                kind = "yaw" if name.startswith("set_") else "dyaw"
                self.has_yaw = True
                self.absolute_yaw = kind == "yaw"
            elif k in ("speed", "velocity", "max_speed"):
                kind = ("constant", 0.01)
            elif k in ("acceleration", "accel"):
                kind = ("constant", 0.05)
            elif k in ("force_limit", "max_force", "contact_force_limit"):
                kind = ("constant", 10.0)
                self.force_limited = True
            elif k in ("wait", "blocking"):
                kind = ("constant", True)

            if kind is not None:
                self.mapping[p.name] = kind
            elif (
                p.default is inspect.Parameter.empty
                and p.kind not in (
                    inspect.Parameter.VAR_POSITIONAL,
                    inspect.Parameter.VAR_KEYWORD,
                )
            ):
                raise ValueError("Unrecognized required motion parameter")

        if rotation_only:
            if not self.has_yaw or self.has_position:
                raise ValueError("Not a standalone yaw command")
        elif not self.has_position:
            raise ValueError("Not a Cartesian translation command")

    def call(self, old_position, new_position, old_yaw, new_yaw):
        dp = [b - a for a, b in zip(old_position, new_position)]
        values = {
            "p": list(new_position),
            "dp": dp,
            "yaw": new_yaw,
            "dyaw": new_yaw - old_yaw,
        }
        for i, axis in enumerate("xyz"):
            values[axis] = new_position[i]
            values["d" + axis] = dp[i]

        args, kwargs = [], {}
        for p in self.signature.parameters.values():
            if p.kind in (
                inspect.Parameter.VAR_POSITIONAL,
                inspect.Parameter.VAR_KEYWORD,
            ):
                continue
            if p.name in self.mapping:
                kind = self.mapping[p.name]
                value = kind[1] if isinstance(kind, tuple) else values[kind]
            elif p.kind == inspect.Parameter.POSITIONAL_ONLY:
                value = p.default
            else:
                continue
            if p.kind == inspect.Parameter.POSITIONAL_ONLY:
                args.append(value)
            else:
                kwargs[p.name] = value
        return self.fn(*args, **kwargs)


def _find_motion(api):
    candidates = []
    for name in (
        "move_to", "move_cartesian", "cartesian_move", "move_tcp",
        "move_delta", "move_relative", "move", "translate",
        "set_tcp_position", "set_position",
    ):
        fn = getattr(api, name, None)
        if not callable(fn):
            continue
        try:
            candidates.append(_Motion(fn, name))
        except (TypeError, ValueError):
            pass

    if not candidates:
        raise RuntimeError(
            "No identifiable Cartesian motion interface. "
            "Expose its signature rather than guessing joint/action semantics."
        )

    candidates.sort(
        key=lambda m: (m.has_yaw, m.force_limited, m.absolute_yaw),
        reverse=True,
    )
    motion = candidates[0]
    rotation = None
    if not motion.has_yaw:
        for name in ("set_yaw", "rotate_to", "rotate_yaw", "rotate_z", "rotate"):
            fn = getattr(api, name, None)
            if not callable(fn):
                continue
            try:
                rotation = _Motion(fn, name, rotation_only=True)
                break
            except (TypeError, ValueError):
                pass
        if rotation is None:
            raise RuntimeError("Cartesian translation exists, but no yaw control was found.")
    return motion, rotation


class _Controller:
    def __init__(self, api):
        self.api = api
        self.motion, self.rotation = _find_motion(api)
        self.pose_readers = _zero_argument_methods(
            api,
            ("get_tcp_pose", "tcp_pose", "get_pose", "pose",
             "get_tcp", "get_state", "observe", "state"),
        )
        self.force_readers = _zero_argument_methods(
            api,
            ("get_wrench", "wrench", "get_tcp_wrench",
             "get_force", "force", "contact_force"),
        )

        # The trace is the fallback, not a presumed reset configuration.
        self.p = [0.4564, 0.0656, 0.1672]
        self.yaw = 0.0
        self.yaw_known = False
        self.measured_position = False
        self.force = None
        self.refresh()
        self.baseline_force = self.force
        self.safe_z = max(self.p[2], 0.1672)

    def check_done(self):
        if self.api.done():
            raise _Finished()

    def refresh(self, result=None):
        self.measured_position = False

        # A bare motion return might be a wrench or status vector, not a pose.
        parsed = _pose(result) if isinstance(result, dict) else None
        force = _force(result)
        for fn in self.pose_readers:
            value = fn()
            if parsed is None:
                parsed = _pose(value)
            if force is None:
                force = _force(value)
            if parsed is not None:
                break

        if parsed is not None:
            self.p, yaw = parsed
            self.measured_position = True
            if yaw is not None:
                self.yaw = yaw
                self.yaw_known = True

        for fn in self.force_readers:
            sensed = _force(fn(), True)
            if sensed is not None:
                force = sensed
                break
        self.force = force

    def force_change(self):
        if self.force is None:
            return None
        baseline = self.baseline_force
        if baseline is None or len(baseline) != len(self.force):
            baseline = (0.0,) * len(self.force)
        return math.sqrt(sum((a - b) ** 2 for a, b in zip(self.force, baseline)))

    def command(self, position, yaw):
        self.check_done()
        old_p, old_yaw = self.p[:], self.yaw

        if self.rotation is not None and abs(yaw - old_yaw) > 1e-8:
            result = self.rotation.call(old_p, old_p, old_yaw, yaw)
            self.yaw = yaw
            self.check_done()
            self.refresh(result)
            old_p, old_yaw = self.p[:], self.yaw

        result = self.motion.call(old_p, position, old_yaw, yaw)
        self.p = list(position)
        self.yaw = yaw
        self.check_done()
        self.refresh(result)

    def goto(self, position, yaw=None):
        """Free-space movement; never use this to push through contact."""
        if yaw is None:
            yaw = self.yaw
        stalls = 0
        for _ in range(1000):
            dp = [b - a for a, b in zip(self.p, position)]
            distance = math.sqrt(sum(v * v for v in dp))
            da = yaw - self.yaw
            if distance < 0.00005 and abs(da) < 0.001:
                return
            scale = min(
                1.0,
                0.008 / max(distance, 1e-12),
                0.04 / max(abs(da), 1e-12),
            )
            before = self.p[:]
            self.command(
                [a + scale * d for a, d in zip(self.p, dp)],
                self.yaw + scale * da,
            )
            progress = math.dist(before, self.p)
            if distance > 0.0001 and self.measured_position and progress < 0.00001:
                stalls += 1
                if stalls >= 2:
                    raise RuntimeError("Free-space motion stalled; stopping.")
            else:
                stalls = 0
        raise RuntimeError("Motion did not converge.")

    def insert(self, x, y):
        # Do not assume whether TCP is at the tip or at the upper peg end.
        # Check success every 0.5 mm; contact/stall detection bounds travel.
        for _ in range(400):
            self.check_done()
            load = self.force_change()
            if load is not None and load >= 8.0:
                return False

            guarded = self.motion.force_limited
            if not self.measured_position and self.force is None and not guarded:
                raise RuntimeError(
                    "Insertion requires pose feedback, force feedback, "
                    "or a force-limited Cartesian command."
                )

            if self.p[2] <= 0.019:
                return False

            old_z = self.p[2]
            target_z = max(0.019, old_z - 0.0005)
            self.command([x, y, target_z], self.yaw)

            load = self.force_change()
            if load is not None and load >= 8.0:
                return False
            if self.measured_position and old_z - self.p[2] < 0.0001:
                return False
        return False


def _estimate_hole(api):
    """Average raw yaw noise; do not fold each noisy sample modulo pi/2."""
    mean = [0.0, 0.0, 0.0]
    m2 = [0.0, 0.0, 0.0]
    count = 0
    top = 0.05

    for attempt in range(8192):
        if attempt % 64 == 0 and api.done():
            raise _Finished()
        value = _pose(api.hole_pose())
        if value is None or value[1] is None:
            continue
        p, yaw = value

        # Yaw's stated prior is near zero. Unwrap at +/-pi, not +/-pi/4.
        yaw = (yaw + math.pi) % (2.0 * math.pi) - math.pi
        sample = [p[0], p[1], yaw]
        count += 1
        for i, v in enumerate(sample):
            d = v - mean[i]
            mean[i] += d / count
            m2[i] += d * (v - mean[i])
        top = p[2]

        if count >= 256 and count % 64 == 0:
            se = [math.sqrt(v / (count - 1) / count) for v in m2]
            if max(se[:2]) <= 0.00004 and se[2] <= 0.01:
                break
        if count >= 4096:
            break

    if count < 32:
        raise RuntimeError("Insufficient valid hole measurements.")

    # The observations disagree with the nominal placement range. Do not
    # project them onto that range and thereby introduce centimetres of error.
    return mean[0], mean[1], top, mean[2]


def run(api):
    try:
        if api.done():
            return

        control = _Controller(api)
        x, y, top, yaw = _estimate_hole(api)

        # Initial trace height clears the surface even with an 80 mm TCP offset.
        control.safe_z = max(control.safe_z, top + 0.08 + 0.025)
        control.goto([control.p[0], control.p[1], control.safe_z])

        yaw_actuator = control.rotation or control.motion
        if control.yaw_known or yaw_actuator.absolute_yaw:
            # Square symmetry: select the nearest equivalent orientation.
            yaw += round((control.yaw - yaw) / (math.pi / 2)) * (math.pi / 2)
            angular_offsets = [
                0.0,
                math.radians(1.0), math.radians(-1.0),
                math.radians(2.0), math.radians(-2.0),
            ]
            trials = [(x, y, yaw + da) for da in angular_offsets]
            for dx, dy in (
                (0.00015, 0.0), (-0.00015, 0.0),
                (0.0, 0.00015), (0.0, -0.00015),
            ):
                trials.extend(
                    (x + dx, y + dy, yaw + da)
                    for da in angular_offsets[:3]
                )
        else:
            # Relative yaw control without orientation sensing: use a virtual
            # yaw coordinate and cover one complete square-symmetry period.
            # Every rotation occurs after retracting clear of the surface.
            start = control.yaw
            trials = [
                (x, y, start + i * math.pi / 120.0)
                for i in range(60)
            ]

        for tx, ty, angle in trials:
            control.check_done()

            # Retract vertically before changing lateral position or yaw.
            control.goto([control.p[0], control.p[1], control.safe_z])
            control.goto([tx, ty, control.safe_z], angle)

            # This height is above the surface for either common TCP convention.
            approach_z = max(top + 0.08 + 0.005, 0.135)
            control.goto([tx, ty, approach_z], angle)

            if control.insert(tx, ty):
                return

            control.check_done()
            control.goto([control.p[0], control.p[1], control.safe_z])

        control.check_done()
        raise RuntimeError(
            "Bounded insertion search exhausted; peg retracted. "
            "Inspect pose calibration and contact feedback before retrying."
        )
    except _Finished:
        return
