"""Conservative, resumable peg-in-hole controller.

No reset, joint commands, or guessed action-vector layouts are used. If the
Cartesian interface or required feedback cannot be identified, run() prints
the available signatures and returns an actionable diagnostic without moving.
"""

import inspect
import math
import re


SURFACE_Z = 0.05
TARGET_TIP_Z = SURFACE_Z - 0.031
CLEARANCE_Z = SURFACE_Z + 0.004
PROBE_Z = SURFACE_Z - 0.0007

XY_BOUNDS = ((0.40, 0.50), (-0.05, 0.05))
GRID_PITCH = 0.0005
MAX_TRANSLATION_STEP = 0.0005
MAX_YAW_STEP = math.radians(1.0)
MAX_NORMAL_FORCE = 8.0
MAX_LATERAL_FORCE = 4.0
MAX_PROBES = 10000


class InterfaceRequired(Exception):
    pass


class GuardStop(Exception):
    pass


def _inventory(api):
    result = {}
    for name in dir(api):
        if name.startswith("_"):
            continue
        try:
            member = getattr(api, name)
        except Exception:
            continue
        if not callable(member):
            continue
        try:
            signature = inspect.signature(member)
        except (TypeError, ValueError):
            signature = None
        result[name] = {
            "call": member,
            "signature": signature,
            "doc": inspect.getdoc(member) or "",
        }
    return result


def _report(inventory):
    lines = []
    for name, entry in sorted(inventory.items()):
        signature = entry["signature"]
        lines.append(
            "{}{}".format(name, signature if signature is not None else "(unknown)")
        )
        if entry["doc"]:
            lines.append("  " + entry["doc"].replace("\n", "\n  "))
    return "\n".join(lines)


def _zero_argument_reader(inventory, names):
    for name in names:
        entry = inventory.get(name)
        if not entry or entry["signature"] is None:
            continue
        try:
            entry["signature"].bind()
        except TypeError:
            continue
        return entry["call"], entry["doc"]
    return None, ""


def _vector(value, size):
    try:
        result = tuple(float(x) for x in value)
    except (TypeError, ValueError):
        return None
    if len(result) != size or not all(math.isfinite(x) for x in result):
        return None
    return result


def _flatten(mapping, output=None):
    if output is None:
        output = {}
    if isinstance(mapping, dict):
        for key, value in mapping.items():
            key = str(key).lower()
            if isinstance(value, dict):
                _flatten(value, output)
            else:
                output.setdefault(key, value)
    return output


def _first(mapping, names):
    for name in names:
        if name in mapping:
            return mapping[name]
    return None


def _find_motion(inventory):
    """Accept only an explicitly world/base-frame Cartesian delta interface."""
    axes = (
        ("dx", "dy", "dz"),
        ("delta_x", "delta_y", "delta_z"),
        ("dx_m", "dy_m", "dz_m"),
    )
    yaw_names = ("dyaw", "delta_yaw", "dyaw_rad", "delta_yaw_rad")

    for name, entry in inventory.items():
        signature = entry["signature"]
        if signature is None:
            continue

        parameters = signature.parameters
        xyz = next((a for a in axes if all(k in parameters for k in a)), None)
        yaw = next((k for k in yaw_names if k in parameters), None)
        if xyz is None or yaw is None:
            continue

        doc = entry["doc"].lower()
        if not re.search(r"(world|base)[ -_]*(coordinate[ -_]*)?frame", doc):
            continue
        if "millimeter" in doc or "millimetre" in doc:
            continue

        metre_units = (
            xyz[0].endswith("_m")
            or re.search(r"\b(meters|metres|meter|metre)\b", doc)
        )
        radian_units = yaw.endswith("_rad") or "radian" in doc
        degree_units = "degree" in doc and not radian_units
        if not metre_units or not (radian_units or degree_units):
            continue

        supplied = {k: 0.0 for k in xyz}
        supplied[yaw] = 0.0
        try:
            signature.bind(**supplied)
        except TypeError:
            continue

        function = entry["call"]

        def move(delta, delta_yaw, fn=function, keys=xyz, angle=yaw,
                 degrees=degree_units):
            arguments = dict(zip(keys, delta))
            arguments[angle] = (
                math.degrees(delta_yaw) if degrees else delta_yaw
            )
            return fn(**arguments)

        return move

    raise InterfaceRequired(
        "Expose a Cartesian displacement method with named dx/dy/dz and "
        "dyaw parameters, documented translation/angular units, and an "
        "explicit world/base frame. Generic action or joint arguments "
        "will not be guessed."
    )


def _find_feedback(inventory):
    reader, state_doc = _zero_argument_reader(
        inventory,
        ("get_state", "observe", "get_observation", "observation", "state"),
    )
    if reader is None:
        raise InterfaceRequired(
            "Expose a zero-argument state reader returning named feedback fields."
        )

    wrench_reader, wrench_doc = _zero_argument_reader(
        inventory, ("get_wrench", "wrench", "get_force_torque")
    )
    documentation = (state_doc + "\n" + wrench_doc).lower()

    def read():
        raw = reader()
        if not isinstance(raw, dict):
            raise InterfaceRequired(
                "State feedback must identify fields; an unlabeled pose/action "
                "vector is not sufficient."
            )
        state = _flatten(raw)

        tip = _vector(
            _first(state, ("peg_tip_position_world", "tip_position_world")), 3
        )
        if tip is None:
            candidate = _first(state, ("peg_tip_position", "tip_position"))
            if "world" in documentation or "base frame" in documentation:
                tip = _vector(candidate, 3)

        # TCP is deliberately not assumed to be the peg tip.
        if tip is None and re.search(
            r"tcp\s+(?:is|at|coincides with)\s+(?:the\s+)?peg tip",
            documentation,
        ):
            tip = _vector(
                _first(state, ("tcp_position", "tcp_pos", "tcp")), 3
            )
        if tip is None:
            raise InterfaceRequired(
                "Expose the peg-tip position in the world/base frame, or "
                "explicitly document that TCP is the peg tip. The 80 mm peg "
                "length alone does not establish the TCP-to-tip transform."
            )

        yaw = _first(state, ("peg_yaw_rad", "tcp_yaw_rad", "yaw_rad"))
        if yaw is None and "radian" in documentation:
            yaw = _first(state, ("peg_yaw", "tcp_yaw", "yaw"))
        try:
            yaw = float(yaw)
        except (TypeError, ValueError):
            raise InterfaceRequired("Expose the current peg yaw in radians.")
        if not math.isfinite(yaw):
            raise InterfaceRequired("Non-finite yaw feedback.")

        force = _vector(
            _first(state, ("force_world_n", "contact_force_world_n")), 3
        )
        if force is None:
            extra = wrench_reader() if wrench_reader else None
            fields = _flatten(extra) if isinstance(extra, dict) else {}
            force = _vector(
                _first(fields, ("force_world_n", "contact_force_world_n")), 3
            )

        if force is None:
            raise InterfaceRequired(
                "Expose a gravity-compensated contact-force vector in world "
                "coordinates and newtons as force_world_n or "
                "contact_force_world_n."
            )
        return tip, yaw, force

    return read


def _square_angle(angle):
    return (angle + math.pi / 4.0) % (math.pi / 2.0) - math.pi / 4.0


class Controller:
    def __init__(self, api, move, read):
        self.api = api
        self.move = move
        self.read = read

    @staticmethod
    def overloaded(force):
        return (
            abs(force[2]) > MAX_NORMAL_FORCE
            or math.hypot(force[0], force[1]) > MAX_LATERAL_FORCE
        )

    def goto(self, target, yaw=None, retract=False):
        previous_error = None
        stalled = 0
        for _ in range(3000):
            if self.api.done():
                return "done"

            position, current_yaw, force = self.read()
            error = tuple(target[i] - position[i] for i in range(3))
            angular_error = (
                0.0 if yaw is None else _square_angle(yaw - current_yaw)
            )

            if retract:
                # Recovery is strictly upward, without rotation or lateral motion.
                if math.hypot(error[0], error[1]) > 0.0001 or yaw is not None:
                    raise GuardStop("Invalid recovery trajectory.")
            elif self.overloaded(force):
                return "contact"

            distance = math.sqrt(sum(x * x for x in error))
            if distance < 0.00005 and abs(angular_error) < math.radians(0.05):
                return "reached"

            combined_error = distance + 0.01 * abs(angular_error)
            if previous_error is not None:
                stalled = stalled + 1 if combined_error >= previous_error - 1e-6 else 0
            if stalled >= 5:
                return "stalled"
            previous_error = combined_error

            scale = min(1.0, MAX_TRANSLATION_STEP / max(distance, 1e-12))
            delta = tuple(x * scale for x in error)
            delta_yaw = max(-MAX_YAW_STEP, min(MAX_YAW_STEP, angular_error))
            self.move(delta, delta_yaw)

        raise GuardStop("Motion iteration limit reached.")

    def lift(self):
        position, _, _ = self.read()
        target = (position[0], position[1], max(position[2], CLEARANCE_Z))
        result = self.goto(target, retract=True)
        if result not in ("reached", "done"):
            raise GuardStop("Retraction did not make progress.")
        return result

    def attempt(self, x, y, yaw):
        if self.lift() == "done":
            return True

        position, _, _ = self.read()
        result = self.goto((x, y, position[2]), yaw=yaw)
        if result == "done":
            return True
        if result != "reached":
            raise GuardStop("Unexpected obstruction above the hole.")

        result = self.goto((x, y, PROBE_Z))
        if result == "done":
            return True
        if result != "reached":
            self.lift()
            return False

        # Entry has been observed, rather than inferred from a command.
        result = self.goto((x, y, TARGET_TIP_Z))
        if result == "done" or self.api.done():
            return True

        self.lift()
        return False


def _search_locations():
    """Search only the stated placement region, nominal center first."""
    nx = int(round((XY_BOUNDS[0][1] - XY_BOUNDS[0][0]) / GRID_PITCH))
    ny = int(round((XY_BOUNDS[1][1] - XY_BOUNDS[1][0]) / GRID_PITCH))
    locations = [
        (XY_BOUNDS[0][0] + ix * GRID_PITCH,
         XY_BOUNDS[1][0] + iy * GRID_PITCH)
        for ix in range(nx + 1)
        for iy in range(ny + 1)
    ]
    locations.sort(key=lambda p: (p[0] - 0.45) ** 2 + p[1] ** 2)
    return locations


def run(api):
    inventory = _inventory(api)
    manifest = _report(inventory)
    print("Available public API signatures and documentation:\n" + manifest)

    done = getattr(api, "done", None)
    if not callable(done):
        return {"status": "interface_required", "reason": "Missing done()."}
    if done():
        return {"status": "success"}

    # The previous samples cluster near (0.3565, -0.0708), outside BOTH
    # stated placement intervals. Do not move there, clamp them, or average
    # away this systematic inconsistency. No additional hole_pose calls
    # are made until its coordinate frame/calibration is established.
    print(
        "Ignoring prior hole_pose measurements for targeting: they conflict "
        "with the stated world-coordinate placement bounds."
    )

    controller = None
    try:
        move = _find_motion(inventory)
        read = _find_feedback(inventory)
        position, _, force = read()

        if position[2] < CLEARANCE_Z or Controller.overloaded(force):
            raise GuardStop(
                "Initial state is not verified clear and unloaded; an explicit "
                "contact-recovery interface is required before continuing."
            )

        controller = Controller(api, move, read)

        # One-degree spacing covers the stated yaw range. Rotations are
        # performed only after lifting; no blind twisting while inserted.
        yaw_degrees = [0]
        for degrees in range(1, 16):
            yaw_degrees.extend((degrees, -degrees))

        probes = 0
        for x, y in _search_locations():
            for degrees in yaw_degrees:
                if probes >= MAX_PROBES:
                    controller.lift()
                    return {
                        "status": "search_budget_exhausted",
                        "probes": probes,
                        "reason": (
                            "No verified insertion. Correct the hole_pose "
                            "frame/calibration or provide a valid localization "
                            "interface before extending the tactile search."
                        ),
                    }
                probes += 1
                if controller.attempt(x, y, math.radians(degrees)):
                    return {"status": "success", "probes": probes}

        return {"status": "not_seated", "probes": probes}

    except InterfaceRequired as exc:
        return {
            "status": "interface_required",
            "reason": str(exc),
            "available_api": manifest,
        }
    except GuardStop as exc:
        # Do not issue additional speculative motion after a guard failure.
        return {"status": "guard_stop", "reason": str(exc)}
